-- Generated by `chainindex dbt` from chains/base.yaml and abis/AerodromePool.json. Do not edit: change the chain file or ABI and regenerate.
-- Fees(address,uint256,uint256)
{{ config(
    materialized='view',
    schema='events_base',
    alias='aerodrome_pool__fees',
    tags=['chains', 'chain_base'],
) }}

select
    toUInt64(8453) as chain_id,
    address,
    block_number,
    block_time,
    block_hash,
    transaction_hash,
    transaction_index,
    log_index,
    inserted_at,
    concat('0x', substring(substring(topic1, 3, 64), 25, 40)) as sender,
    reinterpretAsUInt256(reverse(unhex(substring(data, 3, 64)))) as amount0,
    reinterpretAsUInt256(reverse(unhex(substring(data, 67, 64)))) as amount1
from {{ source('chain_base', 'logs') }}
where topic0 = '0x112c256902bf554b6ed882d2936687aaeb4225e8cd5b51303c90ca6cf43a8602'
  and address in (select address from {{ ref('base__contracts') }} where contract = 'aerodrome_pool')
  and (block_number, block_hash) not in (
    select block_number, block_hash from {{ source('chain_base', 'orphaned_blocks') }}
  )
